def transform(grid):
    """
    Flood fill from 4s through 0s.
    Find all cells with value 4. From each, do 4-connected flood fill,
    converting all reachable 0 cells to 4.
    """
    n, m = len(grid), len(grid[0])
    working = [[grid[r][c] for c in range(m)] for r in range(n)]

    seed_color = 4
    seed_cells = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] == seed_color:
                seed_cells.append((r, c))

    if not seed_cells:
        return working

    from collections import deque
    queue = deque(seed_cells)
    visited = set(seed_cells)

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if (nr, nc) not in visited and grid[nr][nc] == 0:
                    working[nr][nc] = seed_color
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return working

