    n, m = len(grid), len(grid[0])
    working = [row[:] for row in grid]

    # Find all seed positions (value 4)
    seeds = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 4:
                seeds.append((r, c))

    if not seeds:
        return working

    # BFS flood fill
    queue = deque([s for s in seeds])
    visited = set(seeds)

    while queue:
        r, c = queue.popleft()
        # 4-connectivity directions
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if (nr, nc) not in visited and grid[nr][nc] == 0:
                    working[nr][nc] = 4
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return working

